const query = $input.first().json.query || {};
const verifyToken = $env.WHATSAPP_VERIFY_TOKEN;
if (query['hub.mode'] === 'subscribe' && query['hub.verify_token'] === verifyToken) {
  return [{ json: { status: 200, body: query['hub.challenge'] } }];
}
return [{ json: { status: 403, body: 'Verification failed' } }];

const body = $input.first().json.body || $input.first().json;
let entry, change, value, msg, contact;
try {
  entry = body.entry[0];
  change = entry.changes[0];
  value = change.value;
  msg = value.messages ? value.messages[0] : null;
  contact = value.contacts ? value.contacts[0] : null;
} catch (e) {
  return [{ json: { valid: false } }];
}
if (!msg) {
  return [{ json: { valid: false } }];
}
const type = msg.type;
let text = '';
if (type === 'text') text = msg.text.body;
else if (type === 'interactive' && msg.interactive && msg.interactive.button_reply) text = msg.interactive.button_reply.title;
else if (type === 'interactive' && msg.interactive && msg.interactive.list_reply) text = msg.interactive.list_reply.title;

return [{
  json: {
    valid: type === 'text' || type === 'interactive',
    type,
    phone: msg.from,
    name: contact ? contact.profile.name : '',
    text: (text || '').trim(),
    messageId: msg.id
  }
}];

const rooms = items.map(i => i.json);
const original = $('Code - Extract Message').first().json;
return [{ json: { ...original, rooms } }];

const faqs = items.map(i => i.json);
const prev = $('Aggregate Rooms').first().json;
return [{ json: { ...prev, faqs } }];

const session = items.length ? items[0].json : null;
const prev = $('Aggregate FAQs').first().json;
let sessionState = 'START';
let sessionData = {};
if (session && session.State) {
  sessionState = session.State;
  try { sessionData = JSON.parse(session.Data || '{}'); } catch(e) { sessionData = {}; }
}
return [{ json: { ...prev, sessionState, sessionData, sessionExists: !!session } }];

const text = ($json.text || '').trim();
const lower = text.toLowerCase();
const rooms = $json.rooms || [];
const faqs = $json.faqs || [];
let state = $json.sessionState || 'START';
let data = $json.sessionData || {};

const HOTEL_NAME = $env.HOTEL_NAME || 'ABC Hotel';

const greetings = ['hi','hello','hey','salam','assalam','good morning','good evening','asalam'];
const isGreeting = greetings.some(g => lower === g || lower.startsWith(g + ' ') || lower.startsWith(g + ','));

function matchFaq() {
  for (const f of faqs) {
    const q = (f.Question || '').toLowerCase().trim();
    if (!q) continue;
    if (lower.includes(q) || q.includes(lower)) return f.Answer;
  }
  return null;
}

let replyText = null;
let needsOllama = false;
let ollamaPurpose = null;
let action = { saveBooking: false, resetSession: false };

const faqAnswer = (state === 'START' || state === 'DONE') ? matchFaq() : null;

if (faqAnswer) {
  replyText = faqAnswer;
} else if ((state === 'START' || state === 'DONE') && isGreeting) {
  state = 'ASK_DATES';
  data = {};
  replyText = "Welcome to " + HOTEL_NAME + " \n\nI'm your virtual booking assistant.\n\nI can help you:\n- Book rooms\n- Check availability\n- Tell room prices\n- Explain hotel facilities\n- Answer hotel questions\n\nHow many guests and what are your check-in and check-out dates?";
} else if (state === 'START' || state === 'DONE') {
  state = 'ASK_DATES';
  needsOllama = true;
  ollamaPurpose = 'extract_dates';
} else if (state === 'ASK_DATES') {
  needsOllama = true;
  ollamaPurpose = 'extract_dates';
} else if (state === 'SHOWING_ROOMS') {
  const offered = data.offeredRoomIds || [];
  const upper = text.toUpperCase();
  const picked = offered.filter(id => upper.includes(id));
  if (picked.length === 0) {
    replyText = "Sorry, I didn't catch that. Please reply with the Room ID(s) you'd like, e.g. " + offered.join(', ') + ".";
  } else {
    data.selectedRoomIds = picked;
    state = 'ASK_NAME';
    replyText = "Excellent choice.\n\nTo complete your reservation, I need a few details.\n\nWhat is your full name?";
  }
} else if (state === 'ASK_NAME') {
  if (!text) {
    replyText = 'Please enter your full name.';
  } else {
    data.customerName = text;
    state = 'ASK_CNIC';
    replyText = 'Thank you. Please provide your CNIC number (e.g. 12345-1234567-1).';
  }
} else if (state === 'ASK_CNIC') {
  if (!/^\d{5}-\d{7}-\d{1}$/.test(text)) {
    replyText = 'That CNIC format looks incorrect. Please use the format 12345-1234567-1.';
  } else {
    data.cnic = text;
    state = 'ASK_PHONE';
    replyText = 'Great. What is your contact phone number?';
  }
} else if (state === 'ASK_PHONE') {
  if (!/^[0-9+][0-9 ]{6,}$/.test(text)) {
    replyText = 'Please enter a valid phone number.';
  } else {
    data.phone = text;
    state = 'ASK_EMAIL';
    replyText = 'Thanks. What is your email address?';
  }
} else if (state === 'ASK_EMAIL') {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) {
    replyText = 'That email looks invalid. Please provide a valid email address.';
  } else {
    data.email = text;
    state = 'ASK_ADDRESS';
    replyText = 'Almost done. What is your address?';
  }
} else if (state === 'ASK_ADDRESS') {
  if (!text) {
    replyText = 'Please enter your address.';
  } else {
    data.address = text;
    const nights = data.nights || 1;
    const selectedRooms = rooms.filter(r => (data.selectedRoomIds || []).includes(r['Room ID']));
    const total = selectedRooms.reduce((sum, r) => sum + (parseFloat(r['Price/Night']) || 0), 0) * nights;
    data.totalPrice = total;
    state = 'CONFIRMING';
    const roomList = selectedRooms.map(r => r['Room ID']).join(', ');
    replyText = "Please review your booking:\n\nName: " + data.customerName + "\nRooms: " + roomList + "\nGuests: " + data.guests + "\nCheck-in: " + data.checkin + "\nCheck-out: " + data.checkout + "\nTotal: $" + total + "\n\nReply YES to confirm or NO to cancel.";
  }
} else if (state === 'CONFIRMING') {
  if (/^y(es)?$/i.test(text)) {
    action.saveBooking = true;
    state = 'DONE';
    replyText = null;
  } else if (/^n(o)?$/i.test(text)) {
    action.resetSession = true;
    state = 'START';
    data = {};
    replyText = 'No problem, your booking has been cancelled. Let me know if you would like to start a new booking.';
  } else {
    replyText = 'Please reply YES to confirm or NO to cancel your booking.';
  }
} else {
  state = 'START';
  needsOllama = true;
  ollamaPurpose = 'smalltalk';
}

let ollamaMessages = null;
if (needsOllama) {
  const systemPrompts = {
    extract_dates: "You are a hotel booking assistant NLU engine for " + HOTEL_NAME + ". Extract booking details from the guest's message and reply ONLY with strict JSON, no extra text, no markdown: {\"guests\": number|null, \"rooms_needed\": number|null, \"checkin\": \"YYYY-MM-DD\"|null, \"checkout\": \"YYYY-MM-DD\"|null, \"reply\": \"a short natural follow-up question if any field is missing, otherwise a short confirmation sentence\"}. Assume the current year is 2026 if no year is given. If the message is not about booking, set all fields null and reply naturally and professionally.",
    smalltalk: "You are a friendly, professional booking assistant for " + HOTEL_NAME + ". Reply ONLY with strict JSON, no markdown: {\"reply\": \"your short, professional reply\"}. Keep it concise and offer to help with booking, availability, prices or hotel questions."
  };
  ollamaMessages = [
    { role: 'system', content: systemPrompts[ollamaPurpose] },
    { role: 'user', content: text }
  ];
}

return [{
  json: {
    ...$json,
    state,
    data,
    replyText,
    needsOllama,
    ollamaPurpose,
    ollamaMessages,
    action
  }
}];

let parsed = {};
try {
  const content = ($json.message && $json.message.content) || $json.response || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {};
}

const prev = $('State Router').first().json;
let state = prev.state;
let data = { ...prev.data };
let replyText = parsed.reply || 'Sorry, could you please rephrase that?';

if (prev.ollamaPurpose === 'extract_dates') {
  if (parsed.guests) data.guests = parsed.guests;
  if (parsed.rooms_needed) data.roomsNeeded = parsed.rooms_needed;
  if (parsed.checkin) data.checkin = parsed.checkin;
  if (parsed.checkout) data.checkout = parsed.checkout;

  if (data.guests && data.checkin && data.checkout) {
    const nights = Math.max(1, Math.round((new Date(data.checkout) - new Date(data.checkin)) / 86400000));
    data.nights = nights;
    const rooms = prev.rooms || [];
    const available = rooms.filter(r => r.Status === 'Available');
    if (available.length === 0) {
      replyText = "Thank you for your inquiry.\n\nUnfortunately, we don't have rooms available for those dates.\n\nIf your travel dates are flexible, I'd be happy to check alternative dates or suggest other available room options.";
      state = 'ASK_DATES';
    } else {
      data.offeredRoomIds = available.map(r => r['Room ID']);
      const list = available.map(r => "Room " + r['Room ID'] + "\n" + r['Room Type'] + "\n$" + r['Price/Night'] + "/night\n" + r.Facilities).join('\n\n');
      replyText = "Great news!\n\nWe have these rooms available:\n\n" + list + "\n\nWhich room(s) would you like to reserve? (reply with the Room ID)";
      state = 'SHOWING_ROOMS';
    }
  }
}

return [{ json: { ...prev, state, data, replyText } }];

let session = $json;
let replyText = session.replyText;
let state = session.state;
let data = session.data || {};
let action = session.action || {};

if (action.saveBooking) {
  const rooms = session.rooms || [];
  const selectedRooms = rooms.filter(r => (data.selectedRoomIds || []).includes(r['Room ID']));
  const bookingId = 'BK-' + Math.floor(1000 + Math.random() * 9000);
  data.bookingId = bookingId;
  replyText = "Thank you! Your booking is confirmed.\n\nBooking ID: " + bookingId + "\nRooms: " + (data.selectedRoomIds || []).join(', ') + "\nCheck-in: " + data.checkin + "\nCheck-out: " + data.checkout + "\nTotal: $" + data.totalPrice + "\n\nA confirmation email has been sent. We look forward to welcoming you!";
}
if (action.resetSession) {
  data = {};
}

return [{ json: { ...session, replyText, state, data } }];

const finalized = $('Finalize Response & Actions').first().json;
const ids = finalized.data.selectedRoomIds || [];
return ids.map(id => ({ json: { roomId: id } }));

